<template><AppShell><header class="page-head"><span class="eyebrow"><BrainCircuit :size="15" />SMART TUTOR</span><h1>AI 个性化辅导</h1><p>结合当前画像与课程知识库，给出讲解、追问、练习与引用。</p></header>
  <form class="tutor-input" @submit.prevent="ask(false)"><textarea v-model.trim="question" rows="4" placeholder="输入你卡住的知识点或调试问题…" :disabled="loading"></textarea><div><span><BookOpenCheck :size="16" />将使用当前画像和知识依据</span><button class="primary-btn" :disabled="loading||!question"><Send :size="17" />开始辅导</button></div></form>
  <section v-if="loading" class="tutor-running"><span class="spinner"></span><div><strong>{{ waitingStages[waitingIndex] }}</strong><small>正在运行辅导智能体，页面不会显示虚假进度</small></div></section><p v-if="error" class="form-error">{{ error }}</p>
  <template v-if="answer.answer"><section class="answer-hero"><span>核心回答</span><h2>{{ answer.question||lastQuestion }}</h2><p>{{ answer.answer }}</p><div class="evidence-row"><span><BookOpenCheck :size="15" />{{ references.length }} 条知识引用</span><span><ShieldCheck :size="15" />质量审核 {{ qualityScore }}/100</span></div></section>
    <section v-if="answer.explanation" class="lesson-section"><h2>机制讲解</h2><p>{{ answer.explanation.concept||answer.explanation }}</p><blockquote v-if="answer.explanation.analogy">{{ answer.explanation.analogy }}</blockquote><ol><li v-for="step in answer.explanation.steps||[]" :key="step">{{ step }}</li></ol></section>
    <section v-if="answer.socraticQuestions?.length" class="lesson-section"><h2>苏格拉底式追问</h2><article v-for="item in answer.socraticQuestions" :key="item.id||item.question"><b>{{ item.id||'Q' }}</b><p>{{ item.question||item }}</p></article></section>
    <section v-if="answer.practice?.length" class="lesson-section"><h2>即时练习</h2><article v-for="(item,i) in answer.practice" :key="i"><b>{{ i+1 }}</b><p>{{ item.question||item.title||item }}</p></article></section>
    <section v-if="references.length" class="lesson-section references"><h2>知识引用</h2><ol><li v-for="(item,i) in references" :key="i">[{{ i+1 }}] {{ item.title||item.source||item.name||String(item) }}</li></ol></section>
    <form class="follow-up" @submit.prevent="ask(true)"><input v-model.trim="followUp" aria-label="继续追问" placeholder="继续追问这个知识点…" /><button class="primary-btn" aria-label="发送追问" :disabled="loading||!followUp"><Send :size="17" /></button></form>
  </template></AppShell></template>
<script setup>
import { computed,onBeforeUnmount,ref } from 'vue';import { BookOpenCheck,BrainCircuit,Send,ShieldCheck } from 'lucide-vue-next';import AppShell from '../components/AppShell.vue';import { tutor } from '../services/api.js'
const question=ref(''),followUp=ref(''),answer=ref({}),loading=ref(false),error=ref(''),lastQuestion=ref(''),waitingIndex=ref(0),timer=ref(0);const waitingStages=['理解问题与学习上下文','检索课程知识依据','编排讲解与练习','执行内容质量审核'];const references=computed(()=>answer.value.references||[]);const qualityScore=computed(()=>answer.value.qualityEvaluation?.score||answer.value.review?.score||0)
async function ask(isFollowUp=false){const text=isFollowUp?followUp.value:question.value;if(!text)return;loading.value=true;error.value='';lastQuestion.value=text;waitingIndex.value=0;clearInterval(timer.value);timer.value=setInterval(()=>waitingIndex.value=Math.min(waitingStages.length-1,waitingIndex.value+1),3500);try{const response=await tutor({question:text,previousQuestion:answer.value.question||'',previousAnswer:answer.value.answer||'',followUp:isFollowUp});answer.value=response?.data||response?.data?.result||response?.result||response;if(isFollowUp)followUp.value=''}catch(e){error.value=e.message}finally{loading.value=false;clearInterval(timer.value)}}onBeforeUnmount(()=>clearInterval(timer.value))
</script>
<style scoped>.tutor-input{padding:16px;border:1px solid #dce5e0;border-top:3px solid #176f4b;border-radius:7px;background:white}.tutor-input textarea{width:100%;border:0;outline:0;resize:vertical;line-height:1.65}.tutor-input>div{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:10px;padding-top:10px;border-top:1px solid #dce5e0}.tutor-input>div>span{display:flex;align-items:center;gap:5px;color:#68786f;font-size:9px}.tutor-input .primary-btn{min-height:44px;font-size:11px}.tutor-running{display:grid;grid-template-columns:24px minmax(0,1fr);gap:12px;margin-top:14px;padding:15px;border:1px solid #d7e7de;border-radius:7px;background:#edf5f1;color:#176f4b}.tutor-running strong,.tutor-running small{display:block}.tutor-running strong{font-size:12px}.tutor-running small{margin-top:4px;color:#68786f;font-size:9px}.form-error{padding:12px;background:#fff0ec;color:#a04435;font-size:11px}.answer-hero{margin-top:18px;padding:19px;border:1px solid #d5e1da;border-top:3px solid #176f4b;border-radius:7px;background:white}.answer-hero>span{color:#176f4b;font-size:9px;font-weight:800}.answer-hero h2{margin:8px 0 12px;font-size:16px;line-height:1.5}.answer-hero p{margin:0;color:#40544a;font-size:13px;line-height:1.8}.evidence-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:16px;padding-top:13px;border-top:1px solid #e2e9e5}.evidence-row span{min-height:44px;display:flex;align-items:center;gap:6px;padding:9px 10px;border-radius:5px;background:#edf5f1;color:#176f4b;font-size:10px}.lesson-section{margin-top:12px;padding:18px;border:1px solid #dce5e0;border-radius:7px;background:white}.lesson-section h2{margin:0 0 14px;font-size:15px}.lesson-section>p,.lesson-section blockquote,.lesson-section li,.lesson-section article p{color:#40544a;font-size:12px;line-height:1.7}.lesson-section blockquote{margin:12px 0;padding:10px 12px;border-left:3px solid #a16f19;background:#fff8ec}.lesson-section article{display:grid;grid-template-columns:30px minmax(0,1fr);gap:9px;padding:12px 0;border-top:1px solid #dce5e0}.lesson-section article b{width:27px;height:27px;display:grid;place-items:center;background:#edf5f1;color:#176f4b;font-size:10px}.lesson-section article p{margin:2px 0}.references li{margin:8px 0}.follow-up{position:sticky;bottom:calc(62px + env(safe-area-inset-bottom));z-index:4;display:grid;grid-template-columns:minmax(0,1fr) 48px;gap:7px;margin:14px -6px -8px;padding:8px;background:rgba(246,248,247,.96);backdrop-filter:blur(10px)}.follow-up input{min-height:48px;padding:0 12px;border:1px solid #cfdad4;border-radius:6px;background:white}.follow-up .primary-btn{padding:0}@media (max-width:380px){.tutor-input>div{align-items:stretch;flex-direction:column}.evidence-row{grid-template-columns:1fr}}</style>
